    HHOOK hKeyboardHook = nullptr;

    // Start the hook
    bResult = SetWindowlessKeyboardHook(hwnd, keyboardCallback, &hKeyboardHook);
    if (!bResult) {
        cout << "Failed to install keyboard hook" << endl;
        return 1;
    }

    // Keep the thread alive
    thread t1([hKeyboardHook] {
        while (true) {
            Sleep(1);
        }
    });

