    // Remove the hook
    if (hKeyboardHook) {
        bResult = UninstallWindowlessKeyboardHook(hKeyboardHook, hwnd);
        if (!bResult) {
            cout << "Failed to remove keyboard hook" << endl;
        }
    }

    return 0;
}
```

