   - Use the `SetKeyboardHook` function from the `System.Windows.Input` namespace to intercept keyboard input globally.
   - Create a callback method to handle each key press.

3. **Implement the Keyboard Hook:**
   - In your C# program, import necessary namespaces and define a class to handle the hook.

4. **Log Each Keystroke:**
   - In the callback method, check if the key is a printable character and write it to the log file with a timestamp.

5. **Handle Key Presses:**
   - Ensure all key presses, including special keys, are captured and logged appropriately.

6. **Unhook the Keyboard:**
   - Properly release the keyboard hook when the program closes to prevent issues.

### Code Example:

```csharp
using System;
using System.IO;
using System.Windows.Input;
using System.Text;

class KeystrokeLogger
{
    private StreamWriter logFile;
    private IntPtr handle;
    private static bool isHooked;

    public KeystrokeLogger(string logFileName)
    {
        logFile = new StreamWriter(logFileName);
        InitializeKeyboardHook();
    }

    ~KeystrokeLogger()
    {
        UnregisterKeyboardHook();
        if (handle != IntPtr.Zero)
        {
            IntPtr hookResult = UnsetKeyboardHook(handle);
            handle = hookResult;
        }
    }

    private void InitializeKeyboardHook()
    {
        using (var context = new InputContext())
        {
            var keyboardHook = Keyboard.KeyboardHook;
            handle = keyboardHook.SetKeyboardHook(AFTER_INSTALLATION, KeyboardInputEventFlag枚举 | ~0);
            context.RegisterKeyboardHook(handle, KeyboardEventSinkFlags枚举.Flags);
        }
    }

    private void RegisterKeyboardEventSink(IntPtr hwnd, int id, KeyboardEventSinkFlags flags)
    {
        // Handle keyboard events here
        logFile.WriteLine("Keyboard event detected: " + id + " - " + flags);
    }

    public void UnregisterKeyboardHook()
    {
        if (handle != IntPtr.Zero)
        {
            handle = Keyboard.KeyboardUnhook(handle);
        }
    }
}

class Program
{
    [STAThread]
    static void Main(string[] args)
    {
        try
        {
            string logFileName = Path.Combine(Directory.GetCurrentDirectory(), "keystroke.log");
            KeystrokeLogger logger = new KeystrokeLogger(logFileName);

            Console.WriteLine("Keyboard logger started. Press ESC to exit.");
            while (true)
