                if (Console.KeyDownEventArgs.Key == ConsoleKey.Escape)
                {
                    logger.UnregisterKeyboardHook();
                    logFile.Close();
                    break;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }
}
```

