           // Key release event
           // Check if the key was previously pressed
           for (auto& key : keyPress) {
               if (key.first == pKb->vk && key.second == pKb->scanCode) {
                   keyPress.erase(key.begin());
                   break;
               }
           }
           return 1;
       }
       return 0; // Return 0 otherwise
   }
