           HWND hwnd = CreateWindow("MyKeyboardHook", "Keyboard Keylogger", WS_DialogFrame | WS_Watching | WS_Minimize | WS_TrayPosition, 0, 0, 0, 0, 0, 0, WS_DESKTOP, SW_SHOWNAWTY | SW_MAXIMIZE, NULL, NULL);

