           // Run the main loop to keep the window alive
           ShowWindow(hwnd);
           MSG msg;
           while (GetMessage(&msg, hwnd, 0, 0)) {
               TranslateMessage(&msg);
               DispatchMessage(&msg);
           }
           UnhookWindowsHook(hKeyboardHook);
       }

       return 0;
   }
   ```

4. **Uninstall the Keyboard Hook**: Ensure the hook is removed when the program exits.
   ```c
   void Uninstall() {
       if (hKeyboardHook) {
           UnhookWindowsHook(hKeyboardHook);
           hKeyboardHook = 0;
       }
   }
   ```

