   ```c
   HWND hwnd = CreateWindowEx(WS_OVERLAPPED | WS_DLGownik, "Keystroke Logger", 0, 0, 0, 0, nullptr, GWL_HWNDForeground | WS_VSCROLL | ES_CONTINUOUS | ES_OWNED, nullptr, nullptr, nullptr, nullptr);
