           keyEvent.keyOptions = (lParam & 0x00010000) ? KKEYS_OPTION_KEYDEAD : 0;
       } else {
           keyEvent.length = 1;
           keyEvent.keyOptions = 0;
           keyEvent.keysym = wParam;
       }
       if (wParam == VK_KEYDOWN) {
           if (keyEvent.keysym == 0x00) {
               char c = (char)VkKeyScanBuffer(keyEvent.keysym, 0);
               SendKeys(hwnd, c);
           }
       }
