   }
   ```

8. **Send Keystroke Simulation:**
   - Send the captured keystroke to the window.
   ```c
   void SendKeys(HWND hwnd, char c) {
       INPUT input;
       input.type = INPUT_KEYDOWN;
       input.unionKey.key = c;
       SendInput(hwnd, 1, &input);
   }
   ```

