            currentTimestamp += 1;
            if (currentTimestamp >= MAX_KEYSTROKES) {
                cout << "Max keystrokes reached." << endl;
                releaseKeyboardHook();
                return;
            }
        }
    } else {  // Key is being released
        // No action needed for release event
    }
    return keyboardHook;
}

void releaseKeyboardHook() {
    if (keyboardHook) {
        keyboardHook = SetWindowsHook(NULL, NULL);
        cout << "Keyboard hook released." << endl;
    }
}

// Main function to demonstrate the hook
int main() {
    initializeKeyboardHook();
    cout << "Keyboard hook initialized. Press keys to start logging..." << endl;

    while (true) {
        // Check for maximum keystrokes
        if (currentTimestamp >= MAX_KEYSTROKES) {
            cout << "Keyboard logging stopped." << endl;
            releaseKeyboardHook();
            return;
        }

        // Print current timestamp and keystrokes
        cout << "[" << currentTimestamp << "] " << keystrokes.back() << endl;
        Sleep(100);  // Adjust delay as needed
    }

    return 0;
}
```

