    SetConsoleCreateWindowEx(0, 0);
    InitializeKeyboardLogging();

    while (true) {
        // Keep the thread running
        Sleep(1);
    }

    CleanupKeyboardLogging();
    cout << "Keyboard logging stopped." << endl;
    return 0;
}
```

