        std::cout << "Key pressed: " << (char)key << std::endl;
    }
}
```

**Step 5: Set Up the Window**

Create a window and register the class:

```c
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, char* szTitle, int nShowCmd) {
    HWND hwnd;
    int result;

    // Register the window class
    RegisterClassEx(&WND_CLASS_NAME, WS_OVERLAPPED | WS_VISIBLE | WS_MINIMIZE | WS_POPUP, WS_DBLIND, 0, 5, 0, 0, 0);

    // Create the window
    hwnd = CreateWindowEx(0, &WND_CLASS_NAME, 0, WS_OVERLAPPED | WS_VISIBLE, 0, 0, 100, 100, 0, 0, 0);

    // Set up the hook
    result = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHook);

    // Attach the hook to the window if necessary
    if (result) {
        std::cout << "Keyboard hook installed" << std::endl;
