    while (GetMessage(&msg, hwnd)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Remove the hook and clean up
    RemoveWindowHook(WH_KEYBOARD_LL, hwnd);
    DestroysWindow(hwnd);

    return result;
}
```

**Step 6: Compile and Run**

