```c
#include <windows.h>
#include <stdio.h>
#include <time.h>

#define STRICT
#include <WinUser.h>

void keyboard_hook_proc(HWND hwnd, int event, W_EVENT *event_data) {
    if (event != KEYDOWN) {
        return;
    }

    char key = event_data->wKey;
    // Here, you can process the key press, for example, logging it to a file
