    while (GetMessage(&msg, hwnd)) {
        if (msg.message == WM_KEYDOWN) {
            if (msg.wKey != 0) {
                // Process the key stroke
                printf("Key pressed: %d\n", msg.wKey);
                // Here, 'msg.wKey' contains the ASCII value of the key pressed
