### Sample Code

```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

// Function prototype for the keyboard hook
void keyboardHook(int nCode, int wParam, struct HWND hwnd, struct KBDLLHOOKSTRUCT *lps, int time);
void logKeystroke(int key);

