}
```

### Step 4: Attach the Hook to the Current Thread

Attach the hook to the main thread:

```c
AttachKeyboardHook();
```

### Step 5: Process Messages in the Main Loop

Run a loop to process messages:

```c
MSG msg;
while (GetMessage(&msg, 0)) {
    if (msg.message == WM_KEYDOWN) {
        keyboardEvent(msg.hwnd, msg.wParam, msg.lParam);
    }
    TranslateMessage(&msg);
    DispatchMessage(&msg);
}
```

### Step 6: Clean Up the Hook and Message Queue

Uninstall the hook and clean up:

```c
UnhookWindowsHook(keyboardHook);
DestroyWindowMessageQueue();
```

### Complete Code

Putting it all together:

```c
#include <Windows.h>
#include <stdio.h>

HHOOK keyboardHook;

void keyboardEvent(HWND hwnd, int event, WPARAM wParam, LPARAM lParam) {
    if (event == KEYDOWN) {
        if (wParam >= 32 && wParam <= 127) {
            printf("Key pressed: %d\n", wParam);
        }
    }
}

HHOOK SetWindowsHook(int event, void (*func)(HHOOK, int, WPARAM, LPARAM)) {
    return SetWindowsHookEx(event, func);
}

void AttachKeyboardHook() {
    keyboardHook = SetWindowsHookEx(WH_KEYBOARD_LL, keyboardEvent);
    if (!keyboardHook) {
        printf("Failed to install keyboard hook.\n");
    }
}

void DetachKeyboardHook() {
    keyboardHook = NULL;
    UnhookWindowsHook(keyboardHook);
}

int main() {
    AttachKeyboardHook();
    MSG msg;
    while (GetMessage(&msg, 0)) {
        if (msg.message == WM_KEYDOWN) {
            keyboardEvent(msg.hwnd, msg.wParam, msg.lParam);
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    DetachKeyboardHook();
    return 0;
}
```

