    while (GetMessage(&msg, 0)) {
        if (TranslateMessage(&msg)) {
            DispatchMessage(&msg);
        }
    }

    // Clean up
    Unhook(hHook);
    RemoveMessageQueue(HWND_MESSAGE);

    return 0;
}
```

