#include <windows.h>
#include <windowsx.h>
#include <stdio.h>

#define STRICT
#define WIN32_LEAN_AND_MEAN
#include <winuser.h>

void keyboardHook(struct HWND hwnd, int wEvent, struct WEVENT *event) {
