        if (msg.message == WM_KEYDOWN)
        {
            // Use the hook function to process the key event
            keyboard_hook(hwnd, msg.wParam, (struct W_EVENT*)&msg);
        }

        Sleep(1); // Prevents high CPU usage
    }

    // Cleanup
    UnhookWindowsHook(hook);
    RemoveMessageQueue(hwnd);
    return 0;
}
```

