    HHOOK hook = SetWindowHook(hwnd, WH_KEYBOARD_LL, keyboardHook);

    if (hook == 0) {
        std::cerr << "Failed to install keyboard hook" << std::endl;
        return 1;
    }

    // Initialize message queue
    HWND hQueue = CreateMessageQueue();
    if (!hQueue) {
        std::cerr << "Failed to create message queue" << std::endl;
        return -1;
    }

    // Process messages
    MSG msg;
    while (GetMessageW(&msg, hQueue)) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

