3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install the hook:
     ```c
     int main() {
         HWND hwnd = GetMainWnd();
         HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);

         if (hKeyboardHook == NULL) {
             // Error handling
             cout << "Failed to install keyboard hook!" << endl;
             return 1;
         }

         // Start the message loop
         HWND hwndMain = GetMainWnd();
         MSG msg;
         while (GetMessage(hwndMain, &msg) {
             TranslateMessage(&msg);
             DispatchMessage(hwndMain, msg);
         }

         // Cleanup
         UnhookWindowsHook(hKeyboardHook);
         return 0;
     }
     ```

