```c
#include <windows.h>
#include <windowsx.h>
#include <stdio.h>
#include <iostream>
#include <conio.h>

using namespace std;

LRESULT CALLBACK keyboardHook(int nCode, int wParam, LPARAM lParam) {
    if (nCode == HC_KILLFOCUS) return 0;

    if (wParam == VK_KEYDOWN) {
        // Check if the key is a printable character
        if (wParam == 0x1 && (lParam & 0x20) == 0) {
            // Handle the key press here
            cout << static_cast<char>(wParam);
        }
    }

    return 0;
}

int main() {
