        if (msg.message == WM_KEYDOWN) {
            if ((msg.wParam & 0x20) == 0) { // Check if shift is not pressed
                keyboardHook(0, msg.wParam, lParam);
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(hwnd, msg);
    }

    Unhook(hwnd, hook);
    DestroyWindow(hwnd);
    RemoveMessageQueue(hwnd);

    return 0;
}

// Run the program
