int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hKeyboardHook = 0;

    // Define the keyboard hook function
    keyboardHookProc = MakeProcAddress(GetModule("User32"), "CallNextFunction");

    // Set up the keyboard hook
    hKeyboardHook = SetWindowsHook(hwnd, WH_KEYBOARD_LL, keyboardHookProc);

    // Check if the hook was installed successfully
    if (hKeyboardHook == 0) {
