```c
LLONG_PTR CALLBACK MyKeyboardHook(HWND hwnd, LPMSG msg, UINT state, DWORD dwIDEvent, DWORD dwExtraInfo) {
    if (msg.message == WM_KEYDOWN) {
        char key = (char)msg.wKey;
        printf("Key pressed: %c\n", key);
        // Optional: Log the keystroke to a file
        fprintf(stdout, "Key pressed: %c at %d\n", key, time(NULL));
    }
    return 0;
}
```

In the main function, set up the hook:

```c
HWND hwnd = GetForegroundWindow();
