        return 1;
    }

    // Define the window to attach to
    HWND hwnd = GetMainWnd();
    if (!hwnd) {
        cout << "Error: No main window found." << endl;
        return 1;
    }

    // Set up the keyboard hook
    int (HKL) hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardCallback);

    // Attach the hook to the window
    if (!SetWindowHook(hwnd, hKeyboardHook)) {
        cout << "Error: Failed to set keyboard hook." << endl;
        return 1;
    }

    // Start the hook
    bool success = SetWindowHook(hwnd, hKeyboardHook);
    if (!success) {
        cout << "Error: Failed to start the keyboard hook." << endl;
        return 1;
    }

    // Process messages
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.wParam == WM_KEYDOWN) {
            // Already handled by the hook, so skip
        }
    }

    // Cleanup
    UnhookWindowsHook(hwnd, hKeyboardHook);
    RemoveMessageQueue(hwnd);

    return 0;
}
```

### Step 5: Compile and Run
Compile the code using a compiler that supports C/C++ and link against kernel32.lib. Run it with administrative privileges.

