   ```cpp
   int main() {
       HWND hwnd = GetMainWindow();
       if (!hwnd) {
           std::cerr << "Failed to get the main window." << std::endl;
           return 1;
       }

       HHOOK hook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);
       if (!hook) {
           std::cerr << "Failed to set keyboard hook." << std::endl;
           return 1;
