       // Initialize the message queue
       HWND hwndConsole = CreateWindow("console", "Keyboard Hook", WS_VISIBLE | WSICONICONS, 0, 0, 0, 0, NULL, NULL);
       if (!hwndConsole) {
           std::cerr << "Failed to create console." << std::endl;
           return 1;
