void CALLBACK keyboard_hook(unsigned int event, int hwnd, WPARAM wParam, LPARAM lParam) {
    if (event == WM_KEYDOWN) {
        char key = static_cast<char>(wParam);
        std::cout << "Key pressed: " << key << std::endl;
        // Optionally, store the key in a file or other storage
    }
