    MSG msg;
    while (GetMessage(&msg, hwnd, 0, 0)) {
        if (msg.message == WM_KEYDOWN) {
            KeyboardHook(msg.wParam, msg.hWnd, (W_EVENT*)&msg);
        }
    }

    // Clean up the hook
    Unhook(hook);

    return 0;
}

// Initialize the Windows environment
